def the_readback(case, data):
    """RB — THE READBACK TABLE (THE LOOP's step 6 — the forms on file, no new form): ninety-six rows one per verse, graded against the kin's cells by CALL and the tape's lines by kind; the rows SUPPLIED with their writes; no receipt, the three pointers ahead owed; no state, open or stretch row; no retrograde row"""
    del P_[:]
    ask = case['ask']
    R = data['the_readback']['value']
    if ask == 'the_table':
        ink('22:1-25:19', 'ninety-six verses, %d rows; the grades %s' % (len(R), dict(collections.Counter(r['grade'] for r in R))))
        dat('the table a DATA row (the_readback); every row has kin — by CALL %d, on the tape %d' % (sum(1 for r in R if r['cell']), sum(1 for r in R if r['tape_kind'])))
        return out('the readback table (22:1-25:19) — %d rows one per verse, %s; every row graded against its kin' % (len(R), ', '.join('%s %d' % kv for kv in sorted(collections.Counter(r['grade'] for r in R).items()))), ['accepted'])
    if ask == 'the_supplied_rows':
        sup = [r['verses'] for r in R if r['grade'] == 'SUPPLIED']
        ink('22:1-25:19', "the SUPPLIED rows %s — the twenty lines' first verses and the other laws with no seat before" % (sup,))
        dat("the twenty lines' first verses SUPPLIED with their writes (22:1, 22:5, 22:9, 22:13, 22:22, 23:1, 23:10, 23:16, 23:22, 23:25, 24:1, 24:5, 24:8, 24:10, 24:16, 25:1, 25:4, 25:5, 25:11, 25:17) and the other holes (the nest, the parapet, the assembly's bars, the camp's places, the escaped slave, the refraining, the laborer, the divorcee's remarriage, the retaking, the pledge's court, the lashes' cap, the shoe's rite, the naming, the measures) — %d rows" % (len(sup),))
        return out("the supplied rows — %s: the code's holes compiled at the chapters' own day" % (', '.join(sup),), ['accepted'])
    if ask == 'the_reference_rows':
        ref = [(r['verses'], r['tape_kind'], r['tape_verse']) for r in R if r['tape_kind']]
        ink('22:5, 22:21-24, 23:4-7, 23:10-11, 23:14, 23:19, 23:21-24, 24:1, 24:4-5, 24:7, 24:9, 24:15-19, 24:22, 25:1, 25:5-7, 25:12, 25:15-19', 'the reference rows %s' % (ref,))
        dat("the T1 rows against the tape's lines by kind and first verse — the abomination barred (7:25), Dinah's folly (Genesis 34:7), Sarah's phrase (Genesis 20:3), the inciter's purge (13:7), Moab spared (2:9), Balak's hire and the parting (Numbers 22:5, 24:25), the war's speech (20:1), the camp's unclean (Numbers 5:1, 5:4), the blemished sacrifice (17:1), the hand opened (15:7), the vows' law (Numbers 30:2), the captive wife (21:10), Miriam's stroke (Numbers 12:10), the witnesses' law (19:15), the judges in every gate (16:18), the Hebrew slave's refrain (15:12), the release's blessing (15:1), Judah's levirate, the widow sent and the twins (Genesis 38:8, 38:11, 38:27), Amalek's coming and the blotting sworn (Exodus 17:8, 17:14) — %d rows, never a second act" % (len(ref),))
        return out("the reference rows — %d against the tape's lines (the abomination, Dinah, Sarah, the inciter, Moab, Balak, the war, the camp, the blemished sacrifice, the hand, the vows, the captive, Miriam, the witnesses, the judges, the slave, the release, Judah's levirate, Amalek): never a second write" % (len(ref),), ['accepted'])
    if ask == 'the_receipts':
        rc = data['the_receipts']['value']
        ink('22:1-25:19', 'the receipt seats by the finder %s — NONE in the four chapters; the pointers ahead 24:16 (2 Kings 14:6), 25:19 (1 Samuel 15), 25:9 (27:15)' % (rc,))
        dat("no receipt, footer or header in the four chapters (good_land.receipt_seats(22..25) -> [], [], [], [] — the register file untouched); THE THREE POINTERS AHEAD OWED under the lean pass's debt line — no pointer row this sitting")
        return out("the receipts (22:1-25:19) — none by the finder's own count; the three pointers ahead owed: 24:16 to 2 Kings 14:6, 25:19 to 1 Samuel 15, 25:9 to 27:15", ['accepted'])
    if ask == 'no_state_no_open':
        ink('22:1-25:19', 'pointer rows %s, state rows %s, open rows %s, stretch rows %s' % ([r['verses'] for r in R if r['pointer']], [r['verses'] for r in R if r['state']], [r['verses'] for r in R if r['open']], [r['verses'] for r in R if r['stretch']]))
        dat('the forms on file, no new form — no pointer (the three owed), no state, no open (the disputes recorded with their arms), no stretch')
        return out('no pointer, no state, no open, no stretch row — the forms on file, no new form', ['accepted'])
    if ask == 'the_twin_diffed':
        ink('22:1-25:19', 'the twins diffed on the DB %s' % (TWIN,))
        dat("the reading's kin asserts read again (DK4) — 24:16 with 2 Kings 14:6 twelve, 24:18 with 15:15 fourteen, 24:1 with 24:3 eight, 23:3 with 23:4 eleven, 24:4 with 21:23 ten, 25:15 with 5:16 eight, 22:5 with 25:16 seven")
        return out("the twins diffed — 24:16 vs 2 Kings 14:6 %d, 24:18 vs 15:15 %d, 24:1 vs 24:3 %d, 23:3 vs 23:4 %d, 24:4 vs 21:23 %d, 25:15 vs 5:16 %d, 22:5 vs 25:16 %d: the reading's kin asserts read again" % (TWIN['24:16 vs 2Kgs 14:6'], TWIN['24:18 vs 15:15'], TWIN['24:1 vs 24:3'], TWIN['23:3 vs 23:4'], TWIN['24:4 vs 21:23'], TWIN['25:15 vs 5:16'], TWIN['22:5 vs 25:16']), ['accepted'])
    if ask == 'no_retrograde_row':
        ink('23:5-6, 24:9, 24:18, 24:22, 25:17-18', "Balaam's hire, Miriam's stroke, the slave refrain and Amalek's coming — REMEMBRANCES: REFERENCE rows against the tape's own lines; no narrative verb in the four chapters (22:17's 'saying' the father's speech inside the statute)")
        dat("no retrograde marker, no stretch — the twenty lines own-day at (40, 11, 1); the retellings never a second act")
        return out("no retrograde row — 23:5-6, 24:9, 24:18, 24:22 and 25:17-18 retell as REFERENCE rows; the twenty lines own-day, no marker", ['accepted'])
    return 'no verdict in span', [], list(P_)
